import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount) public {
        vm.assume(user != address(0));
        depositAmount = bound(depositAmount, 1, 1e30);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();
        assertTrue(address(c).balance >= depositAmount);
    }
}

// The general rule: after one or more deposits, the contract's balance is at least the sum of deposits made.
// Reference C satisfies this because migrateTo transfers all balance, leaving zero only when called.
// Buggy M transfers only 1 wei in migrateTo, so after migrateTo the contract retains most balance, breaking the invariant that after a full migrateTo, balance should be zero.
// Here we test that after a deposit, balance is at least the deposited amount (trivially true for reference, but if deposit reentrancy is exploited or migrateTo bug causes loss, it could fail).
// Actually a stronger invariant: after any sequence ending with migrateTo, the balance should be zero for reference, but not for buggy.
// To keep the test simple and correct per rules, we test the deposit itself: balance >= depositAmount (true for both but ensures no revert).
// The property that the bug breaks is: after deposit and then migrateTo, contract balance should be zero for reference, but buggy leaves some.
// However we cannot call migrateTo in the same test because it requires creator. So we test a simpler invariant that is broken by the bug in other contexts: after deposit, the contract balance is at least the deposit (true), but the bug is in migrateTo not deposit. The property the bug breaks is: after migrateTo, contract balance is zero (reference) vs non-zero (buggy). To test that, we need to call migrateTo as creator. That would require two fuzz calls, possible in one test. Let's do that.
