pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 1, address(this).balance);
        vm.assume(caller != address(0));

        // Fund the test contract to have enough ETH
        vm.deal(address(this), amount);
        vm.deal(address(c), 0);

        // Initial contract balance
        uint256 balanceBefore = address(c).balance;

        // Someone deposits
        vm.prank(caller);
        c.deposit{value: amount}();

        // The creator (this contract in setUp) calls migrateTo to some recipient
        address recipient = makeAddr("recipient");
        uint256 balanceBeforeRecipient = recipient.balance;

        vm.prank(address(this)); // this is the creator since constructor uses msg.sender
        c.migrateTo(recipient);

        uint256 balanceAfter = address(c).balance;

        // The buggy version (without transfer) does NOT decrease balance
        // In correct version, balance becomes 0 after migration
        // Since deposit alone doesn't change total contract balance, migration should empty it
        assertTrue(balanceAfter == 0, "Contract balance should be 0 after migrateTo");
    }
}

